"""Status polling endpoints for background jobs."""

from fastapi import APIRouter, Depends, HTTPException
from fastapi.responses import HTMLResponse, JSONResponse
from fastapi.templating import Jinja2Templates
from sqlalchemy.orm import Session
from starlette.requests import Request

from app.db import get_db
from app.models import Unit, Quiz
from app.routes.helpers import get_course_for_user

router = APIRouter()
templates = Jinja2Templates(directory="app/templates")


@router.get(
    "/courses/{slug}/units/{unit_id}/extraction-status-fragment",
    response_class=HTMLResponse,
)
async def unit_extraction_status_fragment(
    request: Request,
    slug: str,
    unit_id: int,
    db: Session = Depends(get_db),
):
    get_course_for_user(request, db, slug)
    unit = db.get(Unit, unit_id)
    if unit is None:
        raise HTTPException(status_code=404)
    return templates.TemplateResponse(
        request,
        "units/partials/extraction_status.html",
        {"status": unit.extraction_status, "slug": slug, "unit_id": unit_id},
    )


@router.get("/courses/{slug}/units/{unit_id}/extraction-status")
async def unit_extraction_status(
    request: Request,
    slug: str,
    unit_id: int,
    db: Session = Depends(get_db),
):
    get_course_for_user(request, db, slug)
    unit = db.get(Unit, unit_id)
    if unit is None:
        raise HTTPException(status_code=404)
    return JSONResponse({"status": unit.extraction_status})


@router.get("/courses/{slug}/quiz/{quiz_id}/seed-status")
async def quiz_seed_status(
    request: Request,
    slug: str,
    quiz_id: int,
    db: Session = Depends(get_db),
):
    get_course_for_user(request, db, slug)
    quiz = db.get(Quiz, quiz_id)
    if quiz is None:
        raise HTTPException(status_code=404)
    return JSONResponse({"status": quiz.seed_status})


@router.get(
    "/courses/{slug}/units/{unit_id}/flashcard-gen-status",
    response_class=HTMLResponse,
)
async def flashcard_gen_status(
    request: Request,
    slug: str,
    unit_id: int,
    db: Session = Depends(get_db),
):
    from app.models import Flashcard
    from datetime import datetime, timezone, timedelta

    get_course_for_user(request, db, slug)
    recent = (
        db.query(Flashcard)
        .filter(
            Flashcard.unit_id == unit_id,
            Flashcard.created_at >= datetime.now(timezone.utc) - timedelta(minutes=5),
        )
        .count()
    )
    if recent > 0:
        return HTMLResponse(
            f'<p style="font-size:13px; color:var(--mastered);">'
            f'{recent} flashcards generated — <a href="" onclick="location.reload();return false;">refresh to review</a></p>'
        )
    return HTMLResponse(
        '<p id="flashcard-gen-status" '
        f'hx-get="/courses/{slug}/units/{unit_id}/flashcard-gen-status" '
        'hx-trigger="every 3s" '
        'hx-swap="outerHTML" '
        'style="font-size:13px; color:var(--text-secondary);">'
        "Generating flashcards…</p>"
    )


@router.get("/courses/{slug}/quiz/{quiz_id}/seed-status-redirect")
async def quiz_seed_status_redirect(
    request: Request,
    slug: str,
    quiz_id: int,
    db: Session = Depends(get_db),
):
    get_course_for_user(request, db, slug)
    quiz = db.get(Quiz, quiz_id)
    if quiz is None:
        raise HTTPException(status_code=404)
    if quiz.seed_status == "ready":
        return HTMLResponse(
            f'<script>window.location="/courses/{slug}/quiz/{quiz_id}/question/1";</script>'
        )
    elif quiz.seed_status == "failed":
        return HTMLResponse(
            '<p style="color:var(--danger); font-size:14px;">Question generation failed. '
            f'<a href="/courses/{slug}">Return to course</a></p>'
        )
    return HTMLResponse(
        '<div id="quiz-seed-poll" '
        f'hx-get="/courses/{slug}/quiz/{quiz_id}/seed-status-redirect" '
        'hx-trigger="every 3s" '
        'hx-swap="outerHTML">'
        '<p style="color:var(--text-tertiary); font-size:13px;">Generating…</p></div>'
    )
